#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
using namespace std;

long long gcdLL(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long lcmLL(long long a, long long b) {
    return a / gcdLL(a, b) * b;
}

struct Fraction {
    long long num;
    long long den;
};

Fraction absFraction(const Fraction& f) {
    return {abs(f.num), f.den};
}

int compareFractions(const Fraction& a, const Fraction& b) {
    long long l = lcmLL(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    if (na == nb) return 0;
    return (na < nb) ? -1 : 1;
}

Fraction subtractFractions(const Fraction& a, const Fraction& b) {
    long long l = lcmLL(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    long long res_num = na - nb;
    long long g = gcdLL(abs(res_num), l);
    return {res_num / g, l / g};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long x, y, n;
    cin >> x >> y >> n;
    long long g = gcdLL(x, y);
    x /= g; y /= g;
    Fraction xy = {x, y};
    Fraction min_diff = {1000000000000LL, 1};
    Fraction min_value = {0, 0};
    for (long long b = 1; b <= n; ++b) {
        long long l = 0, r = 1000000;
        double maxv = (double)x / y + (double)min_diff.num / min_diff.den + 2;
        maxv *= b;
        r = (long long)maxv;
        while (l <= r) {
            long long mid = l + (r - l) / 2;
            Fraction ab = {mid, b};
            Fraction dif = absFraction(subtractFractions(xy, ab));
            int comp = compareFractions(dif, min_diff);
            if (comp == 0) {
                if (ab.den < min_value.den)
                    min_value = ab;
                else if (ab.den == min_value.den && ab.num < min_value.num)
                    min_value = ab;
            } else if (comp < 0) {
                min_diff = dif;
                min_value = ab;
            }
            if (compareFractions(ab, xy) < 0)
                l = mid + 1;
            else
                r = mid - 1;
        }
    }
    cout << min_value.num << "/" << min_value.den;
    return 0;
}
