import java.util.Scanner;

public class Main {
    static long gcdLL(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static long lcmLL(long a, long b) {
        return a / gcdLL(a, b) * b;
    }

    static class Fraction {
        long num;
        long den;

        Fraction(long num, long den) {
            this.num = num;
            this.den = den;
        }
    }

    static Fraction absFraction(Fraction f) {
        return new Fraction(Math.abs(f.num), f.den);
    }

    static int compareFractions(Fraction a, Fraction b) {
        long l = lcmLL(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        if (na == nb) return 0;
        return (na < nb) ? -1 : 1;
    }

    static Fraction subtractFractions(Fraction a, Fraction b) {
        long l = lcmLL(a.den, b.den);
        long na = a.num * (l / a.den);
        long nb = b.num * (l / b.den);
        long res_num = na - nb;
        long g = gcdLL(Math.abs(res_num), l);
        return new Fraction(res_num / g, l / g);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long g = gcdLL(x, y);
        x /= g;
        y /= g;
        Fraction xy = new Fraction(x, y);
        Fraction min_diff = new Fraction(1000000000000L, 1);
        Fraction min_value = new Fraction(0, 0);

        for (long b = 1; b <= n; ++b) {
            long l = 0, r = 1000000;
            double maxv = (double) x / y + (double) min_diff.num / min_diff.den + 2;
            maxv *= b;
            r = (long) maxv;
            while (l <= r) {
                long mid = l + (r - l) / 2;
                Fraction ab = new Fraction(mid, b);
                Fraction dif = absFraction(subtractFractions(xy, ab));
                int comp = compareFractions(dif, min_diff);
                if (comp == 0) {
                    if (ab.den < min_value.den)
                        min_value = ab;
                    else if (ab.den == min_value.den && ab.num < min_value.num)
                        min_value = ab;
                } else if (comp < 0) {
                    min_diff = dif;
                    min_value = ab;
                }
                if (compareFractions(ab, xy) < 0)
                    l = mid + 1;
                else
                    r = mid - 1;
            }
        }
        System.out.println(min_value.num + "/" + min_value.den);
        sc.close();
    }
}
